#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package LibVLCSharp@3.8.0 #:package System.Threading.Channels@8.0.0 #:package Microsoft.Extensions.ObjectPool@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property PublishAot=true  using System.Buffers; using System.Threading.Channels; using LibVLCSharp.Shared;  // 1. 直播流处理器(AOT优化版) [SkipLocalsInit] public sealed class LiveStreamProcessor : IDisposable {     private readonly LibVLC _libVlc;     private readonly ThreadLocal<Span<byte>> _buffer;     private readonly ObjectPool<MediaPlayer> _playerPool;     private readonly TailLatencyOptimizer _latencyOptimizer;          public LiveStreamProcessor()     {         _libVlc = new LibVLC();         _buffer = new(() => stackalloc byte[1920 * 1080 * 4]); // 1080p帧缓冲区         _playerPool = new DefaultObjectPool<MediaPlayer>(             new MediaPlayerPooledPolicy(_libVlc), 8);         _latencyOptimizer = new TailLatencyOptimizer();     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public unsafe void ProcessLiveStream(string streamUrl)     {         var player = _playerPool.Get();         try         {             using var media = new Media(_libVlc, streamUrl);             _latencyOptimizer.Optimize(() => {                 player.Play(media);                                  // 设置零拷贝回调                 player.SetVideoFormatCallbacks(SetupVideoFormat, CleanupVideoFormat);                 player.SetVideoCallbacks(LockVideo, null, DisplayVideo);             });         }         finally         {             _playerPool.Return(player);         }     }      private unsafe VideoFormat SetupVideoFormat(ref BitmapFormat format)     {         // 设置4:2:0 YUV格式         format.Width = 1920;         format.Height = 1080;         format.FourCC = VideoFormat.YV12;         format.PlaneCount = 3;                  // 计算内存对齐的缓冲区大小         int yStride = (format.Width + 31) & ~31; // 32字节对齐         int uvStride = (yStride / 2 + 31) & ~31;         format.Pitches = new int[] { yStride, uvStride, uvStride };         format.Lines = new int[] { format.Height, format.Height / 2, format.Height / 2 };                  return VideoFormat.YV12;     }      private unsafe void DisplayVideo(IntPtr opaque, IntPtr picture)     {         // 使用SIMD加速视频帧处理         var buffer = _buffer.Value;         fixed (byte* ptr = buffer)         {             // 确保内存地址64字节对齐(Cache-line优化)             if ((long)ptr % 64 == 0)             {                 // 将视频帧送入处理管道                 var frame = new VideoFrame(ptr, buffer.Length);                 _latencyOptimizer.Optimize(() => {                     _frameChannel.Writer.TryWrite(frame);                 });             }         }     } }  // 2. 主程序集成 var builder = WebApplication.CreateBuilder(); builder.Services.AddSingleton<LiveStreamProcessor>(); var app = builder.Build(); app.MapGet("/", () => "Live Streaming Ready"); app.Run();   public sealed class TailLatencyOptimizer {     private readonly ThreadLocal<long> _lastProcessTime;     private readonly SpinWait _spinWait;          public TailLatencyOptimizer()     {         _lastProcessTime = new(() => long.MaxValue);         _spinWait = new SpinWait();     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public void Optimize(Action action)     {         long start = Stopwatch.GetTimestamp();         try         {             action();         }         finally         {             long elapsed = Stopwatch.GetTimestamp() - start;             long last = _lastProcessTime.Value;                          // 动态调整等待时间             if (elapsed > last * 1.5)             {                 _spinWait.SpinOnce();             }             _lastProcessTime.Value = elapsed;         }     } }  internal sealed class MediaPlayerPooledPolicy : PooledObjectPolicy<MediaPlayer> {     private readonly LibVLC _libVlc;          public MediaPlayerPooledPolicy(LibVLC libVlc)     {         _libVlc = libVlc;     }      public override MediaPlayer Create()     {         var player = new MediaPlayer(_libVlc);         // 配置硬件加速         player.EnableHardwareDecoding = true;         player.EnableKeyInput = false;         player.EnableMouseInput = false;         return player;     }      public override bool Return(MediaPlayer obj)     {         obj.Stop();         return true;     } }
